#!/usr/bin/env python3
# Removes the checksums Gradle wrote (origin "Generated by Gradle") from
# gradle/verification-metadata.xml and keeps the hand-verified ones (#850).
#
# update-verification.sh --prune calls this instead of deleting the file. Each
# host regenerates its own generated checksums, so pruning them is the point. A
# hand-verified entry is an artifact the three legs cannot resolve (the Binaryen
# macOS x86_64 archive, say), and deleting the file dropped it on every prune.
# Gradle keeps the entries already in the file when it writes, so the hand-verified
# ones survive the run that follows.
#
#   python3 -I scripts/gradle/strip-generated-checksums.py gradle/verification-metadata.xml
import sys
import xml.etree.ElementTree as ET

NS = "https://schema.gradle.org/dependency-verification"
XSI = "http://www.w3.org/2001/XMLSchema-instance"
GENERATED = "Generated by Gradle"


def strip(root):
    components = root.find(f"{{{NS}}}components")
    if components is None:
        return root
    for component in list(components):
        for artifact in list(component):
            for checksum in list(artifact):
                if checksum.get("origin") == GENERATED:
                    artifact.remove(checksum)
            if len(artifact) == 0:
                component.remove(artifact)
        if len(component) == 0:
            components.remove(component)
    return root


def main(path):
    ET.register_namespace("", NS)
    ET.register_namespace("xsi", XSI)
    tree = ET.parse(path)
    strip(tree.getroot())
    tree.write(path, encoding="UTF-8", xml_declaration=True)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: strip-generated-checksums.py <verification-metadata.xml>")
    main(sys.argv[1])
